vector<int> twoSum(vector<int>& nums, int target) {
  unordered_map<int,int> idx;            // 值 -> 下标
  for (int i = 0; i < (int)nums.size(); ++i) {
    auto it = idx.find(target - nums[i]);
    if (it != idx.end()) return {it->second, i};
    idx[nums[i]] = i;                     // 边走边存
  }
  return {};
}

vector<vector<string>> groupAnagrams(vector<string>& s) {
  unordered_map<string, vector<string>> mp;   // key=排序后的词
  for (auto& w : s) {
    string k = w; sort(k.begin(), k.end());
    mp[k].push_back(w);
  }
  vector<vector<string>> ans;
  for (auto& kv : mp) ans.push_back(move(kv.second));
  return ans;
}

vector<int> topKFrequent(vector<int>& nums, int k) {
  unordered_map<int,int> freq;                 // 频次统计
  for (int x : nums) freq[x]++;
  // 用小顶堆维护前 k 大（按频次）
  using P = pair<int,int>;
  priority_queue<P, vector<P>, greater<P>> pq;
  for (auto& kv : freq) {
    pq.push({kv.second, kv.first});
    if ((int)pq.size() > k) pq.pop();
  }
  vector<int> ans; while (!pq.empty()) { ans.push_back(pq.top().second); pq.pop(); }
  return ans;
}
